var spacefastSlugPattern = regexp.MustCompile(`^[a-z0-9](?:[a-z0-9-]{0,53}[a-z0-9])$`)

// spacefastTarget is the parsed target of a spacefast: sink.
type spacefastTarget struct {
	Name   string
	Public bool
}

func parseSpacefastTarget(target string) (spacefastTarget, error) {
	name, opts, _ := strings.Cut(target, ",")
	name = strings.ToLower(strings.TrimSpace(name))
	if !spacefastSlugPattern.MatchString(name) {
		return spacefastTarget{}, fmt.Errorf("--deliver spacefast:<name> needs a name of 2-55 lowercase letters, digits, or hyphens, got %q", name)
	}
	t := spacefastTarget{Name: name}
	for _, opt := range strings.Split(opts, ",") {
		switch strings.TrimSpace(opt) {
		case "":
		case "public":
			t.Public = true
		default:
			return spacefastTarget{}, fmt.Errorf("unknown --deliver spacefast option %q (supported: public)", opt)
		}
	}
	return t, nil
}

