// deliverSpacefast publishes body as a page and prints where it went.
func deliverSpacefast(target string, body []byte) error {
	t, err := parseSpacefastTarget(target)
	if err != nil {
		return err
	}
	api := strings.TrimRight(cliutil.EnvOverride("SPACEFAST_API_URL"), "/")
	if api == "" {
		api = spacefastDefaultAPI
	}
	token := strings.TrimSpace(os.Getenv("SPACEFAST_TOKEN"))
	team := strings.TrimSpace(os.Getenv("SPACEFAST_TEAM"))

	deliveries := loadSpacefastDeliveries()
	prior, havePrior := deliveries[t.Name]
	// A remembered page is only reusable with the credential that owns it.
	if havePrior && (prior.Account != (token != "") || (!prior.Account && prior.Key == "")) {
		havePrior = false
	}

	page := renderSpacefastPage(t.Name, body)
	payload := map[string]any{
		"source": map[string]any{
			"kind":    "agent",
			"client":  spacefastClientVersion,
			"message": "Delivered by printing-press-golden-pp-cli",
		},
	}
	bearer := token
	if havePrior {
		payload["spaceId"] = prior.SpaceID
		if !prior.Account {
			bearer = prior.Key
		}
	} else {
		payload["space"] = map[string]any{"slug": t.Name, "title": spacefastTitle(t.Name)}
		if token != "" && team != "" {
			payload["teamId"] = team
		}
		if t.Public && token != "" {
			payload["access"] = "public"
		}
	}

	receipt, err := spacefastPublish(api, bearer, payload, map[string][]byte{
		"index.html": page,
		"data.json":  spacefastDataFile(body),
	})
	if err != nil {
		return err
	}

	d := spacefastDelivery{SpaceID: receipt.Space.ID, Account: token != ""}
	if havePrior {
		d.Key, d.ClaimURL = prior.Key, prior.ClaimURL
	}
	if receipt.Claim != nil {
		d.Key, d.ClaimURL = receipt.Claim.Key, receipt.Claim.ClaimURL
	}
	// Anonymous pages are private until claimed, so the link to show is the
	// key-bearing door URL (returned only at creation; reused on updates).
	if !d.Account {
		if receipt.Claim != nil {
			d.URL = receipt.Claim.URL
		} else if havePrior {
			d.URL = prior.URL
		}
	}
	if d.URL == "" {
		d.URL = receipt.Space.LiveURL
	}
	if d.URL == "" && receipt.Version.ImmutableURL != "" {
		d.URL = receipt.Version.ImmutableURL
	}
	deliveries[t.Name] = d
	if err := saveSpacefastDeliveries(deliveries); err != nil {
		fmt.Fprintf(os.Stderr, "warning: published, but could not remember the page for later updates: %v\n", err)
	}

	verb := "Published"
	if havePrior {
		verb = "Updated"
	}
	fmt.Fprintf(os.Stderr, "%s on Spacefast: %s\n", verb, spacefastFirstNonEmpty(d.URL, "(URL pending; see the Spacefast dashboard)"))
	if !d.Account && d.ClaimURL != "" {
		fmt.Fprintf(os.Stderr, "Claim it to keep it and share it: %s\n", d.ClaimURL)
		if t.Public && !havePrior {
			fmt.Fprintln(os.Stderr, "note: anonymous pages start private; claim the page to make it public.")
		}
	}
	if receipt.Next.Action == "poll" {
		fmt.Fprintln(os.Stderr, "note: Spacefast is still finalizing; the page will be live in a few seconds.")
	}
	return nil
}

