// spacefastKeyOrder maps each object key to the position it first appears
// in the raw JSON, so table columns keep the command's own field order.
func spacefastKeyOrder(body []byte) map[string]int {
	order := map[string]int{}
	dec := json.NewDecoder(bytes.NewReader(body))
	// One frame per open container. Objects alternate key, value; a frame's
	// wantKey says the next token in that object is a key.
	// Only row objects (direct children of an array) contribute, so an
	// envelope's own keys ({"meta":{"source":…},"results":[…]}) don't
	// claim column slots.
	type frame struct {
		object  bool
		wantKey bool
		row     bool
	}
	var stack []frame
	valueDone := func() {
		if n := len(stack); n > 0 && stack[n-1].object {
			stack[n-1].wantKey = true
		}
	}
	for {
		tok, err := dec.Token()
		if err != nil {
			return order
		}
		if n := len(stack); n > 0 && stack[n-1].object && stack[n-1].wantKey {
			if key, ok := tok.(string); ok {
				if _, seen := order[key]; !seen && stack[n-1].row {
					order[key] = len(order)
				}
				stack[n-1].wantKey = false
				continue
			}
		}
		switch tok {
		case json.Delim('{'):
			inArray := len(stack) > 0 && !stack[len(stack)-1].object
			stack = append(stack, frame{object: true, wantKey: true, row: inArray})
		case json.Delim('['):
			stack = append(stack, frame{})
		case json.Delim('}'), json.Delim(']'):
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
			valueDone()
		default:
			valueDone()
		}
	}
}

func renderSpacefastPage(name string, body []byte) []byte {
	var parsed any
	isJSON := json.Unmarshal(bytes.TrimSpace(body), &parsed) == nil

	var content strings.Builder
	if rows, ok := spacefastRows(parsed); isJSON && ok {
		// Columns in the order the command emitted them (Go maps drop it).
		order := spacefastKeyOrder(body)
		var cols []string
		seen := map[string]bool{}
		for _, r := range rows {
			keys := make([]string, 0, len(r))
			for k := range r {
				keys = append(keys, k)
			}
			sort.SliceStable(keys, func(i, j int) bool {
				oi, iok := order[keys[i]]
				oj, jok := order[keys[j]]
				if iok != jok {
					return iok
				}
				if oi != oj {
					return oi < oj
				}
				return keys[i] < keys[j]
			})
			for _, k := range keys {
				if !seen[k] && len(cols) < spacefastMaxTableCols {
					seen[k] = true
					cols = append(cols, k)
				}
			}
		}
		shown := rows
		if len(shown) > spacefastMaxTableRows {
			shown = shown[:spacefastMaxTableRows]
		}
		fmt.Fprintf(&content, "<p class=\"meta\">%d rows", len(rows))
		if len(shown) < len(rows) {
			fmt.Fprintf(&content, " (first %d shown)", len(shown))
		}
		content.WriteString(" · <a href=\"data.json\">data.json</a></p>\n<div class=\"wrap\"><table>\n<thead><tr>")
		for _, c := range cols {
			fmt.Fprintf(&content, "<th>%s</th>", html.EscapeString(c))
		}
		content.WriteString("</tr></thead>\n<tbody>\n")
		for _, r := range shown {
			content.WriteString("<tr>")
			for _, c := range cols {
				cell := spacefastCell(r[c])
				if strings.HasPrefix(cell, "https://") && !strings.ContainsAny(cell, " \"<>") {
					fmt.Fprintf(&content, "<td><a href=\"%s\">%s</a></td>", html.EscapeString(cell), html.EscapeString(cell))
				} else {
					fmt.Fprintf(&content, "<td>%s</td>", html.EscapeString(cell))
				}
			}
			content.WriteString("</tr>\n")
		}
		content.WriteString("</tbody></table></div>\n")
	} else {
		text := string(body)
		if isJSON {
			if pretty, err := json.MarshalIndent(parsed, "", "  "); err == nil {
				text = string(pretty)
			}
		}
		fmt.Fprintf(&content, "<pre>%s</pre>\n", html.EscapeString(text))
	}

	title := html.EscapeString(spacefastTitle(name))
	stamp := time.Now().UTC().Format("Jan 2, 2006 15:04 UTC")
	var page strings.Builder
	page.WriteString("<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\">\n")
	page.WriteString("<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n")
	fmt.Fprintf(&page, "<title>%s</title>\n", title)
	page.WriteString(`<style>
:root{--bg:#fbfaf7;--fg:#1d1d1b;--muted:#6b6a65;--line:#e4e1d9;--head:#f1eee6;--accent:#2f5d50}
@media (prefers-color-scheme:dark){:root{--bg:#141413;--fg:#ecebe6;--muted:#9a988f;--line:#2c2b28;--head:#1e1d1b;--accent:#8cc5b3}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.5 ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}
main{max-width:1200px;margin:0 auto;padding:32px 16px 48px}h1{font-size:26px;margin:0 0 4px;letter-spacing:-.01em}
.meta{color:var(--muted);font-size:13px;margin:0 0 20px}a{color:var(--accent)}
.wrap{overflow-x:auto;border:1px solid var(--line);border-radius:10px}
table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}
th,td{padding:8px 12px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top;white-space:nowrap;max-width:420px;overflow:hidden;text-overflow:ellipsis}
th{background:var(--head);font-weight:600;font-size:13px;position:sticky;top:0}tbody tr:last-child td{border-bottom:0}
pre{background:var(--head);border:1px solid var(--line);border-radius:10px;padding:16px;overflow-x:auto;font-size:13px}
footer{color:var(--muted);font-size:12px;margin-top:28px}
</style></head><body><main>
`)
	fmt.Fprintf(&page, "<h1>%s</h1>\n<p class=\"meta\">From <code>printing-press-golden-pp-cli</code> · %s</p>\n", title, stamp)
	page.WriteString(content.String())
	page.WriteString("<footer>Printed by the CLI Printing Press · hosted on Spacefast</footer>\n</main></body></html>\n")
	return []byte(page.String())
}
